        let pending_anchor: ReferenceAnchor = self.anchor.load(index: bank)
        let (cx_s, cx) = from_qf_offset<8>(
            pending_anchor.x0,
            pending_anchor.x1,
            pending_anchor.x2,
            pending_anchor.x3,
            0.0,
        )
        let (cy_s, cy) = from_qf_offset<8>(
            pending_anchor.y0,
            pending_anchor.y1,
            pending_anchor.y2,
            pending_anchor.y3,
            0.0,
        )
